export type Tone = "A" | "B" | "C";
export type Situation = { id: string; categoryId: string; title: string; context: string; messages: Record<Tone, string> };
export const tones: { id: Tone; label: string; guidance: string }[] = [
  { id: "A", label: "Profissional", guidance: "Clareza, objetividade e cordialidade." },
  { id: "B", label: "Próxima", guidance: "Conversa natural, simples e leve." },
  { id: "C", label: "Acolhedora", guidance: "Escuta, gentileza e respeito ao momento." },
];
const situation = (id: string, title: string, context: string, A: string, B: string, C: string): Situation => ({ id, categoryId: id.split(".")[0], title, context, messages: { A, B, C } });

